insert into public.branch_policies (branch_id, request_window_days, same_day_always_request, auto_confirm_weekdays, allow_overlap, booking_rules) values
  ((select id from public.branches where code = 'shebin'), 1, false, '{}'::smallint[], false, array['حالة الحجز: لو الميعاد النهاردة أو بكرة ← Confirmed، وبعد كده ← Open. الاستثناء: د. بسنت عوارة ود. هبة غنيم الحجز معاهم Open دايمًا.', 'د. زينب ود. آية الجرواني ود. ماهيتاب ومارينا: نحجز مفيش مشكلة في نفس اليوم لو حد اتصل، إلا لو أنا مبلغة إن الدكتورة هتمشي بدري.', 'د. علا جاب الله هي بس اللي منعملش أوفر لاب وقت ما السيستم يبقى مليان قدامنا، لأنها بتاخد وقتها في السيشن شوية.', 'أي دكتورة بتشتغل ليزر لو الحالة Male عادي، باستثناء: د. علا جاب الله (تحديد دقن وأندر أرم بس)، د. مارينا صلاح (تحديد دقن وأندر أرم بس)، د. زينب الدالي (تحديد دقن بس). باقي الدكاترة عادي مفيش مشكلة لو في بطن أو ضهر أو كده.', 'يوم السبت: ممنوع أي ليزر يتحجز بعد الساعة ٦ لدكتورة ماهيتاب (مهم).', 'يوم الأربع: ممنوع أي ليزر بعد الساعة ٥ لدكتورة علا جاب الله (مهم).', 'ياريت أي أوفر لاب في الحجز ما يتعملش، لأن الحجوزات اللي في نفس الوقت بتعمل مشاكل مع الحالات. لو حصل واتعمل أوفر لاب لازم يبقى من خلال الفرع، ولو الحالة عايزة معاد يتبعت Open ببياناتها واضحة، وهيتم التواصل من خلال الفرع ويتعملها Confirm من عندنا.', 'أوقات الحجز الفاضية: بتتبعت بيانات الحالة وتتعمل Open مادام المواعيد فاضية، والكول سنتر يأكد عادي علشان نوفر وقت العميلة في الحجز.', 'مواعيد الدكاترة ثابتة، ولو في أي Update هيتبلّغ بيه، سواء دكتورة بتغطي دكتورة تانية أو دكتورة إجازة من اليوم خالص.']::text[])
on conflict (branch_id) do update set
  request_window_days = excluded.request_window_days, same_day_always_request = excluded.same_day_always_request,
  auto_confirm_weekdays = excluded.auto_confirm_weekdays, allow_overlap = excluded.allow_overlap,
  booking_rules = excluded.booking_rules;
